package ai.shuvrajeetkamila.mumbai.render;

/**
 * Every texture in the game, generated by arithmetic.
 *
 * <p>There is not one imported image in this project, and that is not a
 * limitation being made the best of. A procedural atlas is a few hundred
 * lines and a few milliseconds at startup, it adds nothing to the APK, and
 * nobody can claim it.
 *
 * <p><b>The tiles are seamless and that is a hard requirement.</b> UVs are
 * derived from world position in the fragment shader, so a tile repeats
 * across a kilometre of road. A visible seam would print a grid over the
 * entire city. Every noise lookup here wraps with {@code floorMod} against a
 * period that divides {@link #SIZE}, which is what makes the left edge
 * continue into the right one. {@code TextureLibraryTest} measures the seam
 * and fails if any tile drifts.
 *
 * <p><b>The alpha channel is not opacity.</b> Everything rendered with these
 * is opaque. Alpha carries the <i>emissive mask</i>: 255 where a surface is a
 * window that should light up after dark, 0 everywhere else. That is what
 * lets a tower glow at its windows at night instead of the whole slab
 * fluorescing, which is what happens when emission is a per-face constant.
 *
 * <p>Colours are multiplied against the per-vertex albedo that the mesher
 * already computes from the OSM class, so these are mostly near white with
 * the pattern carried in the darker values. A texture that supplied its own
 * strong colour would flatten the variety the map data gives us.
 */
public final class TextureLibrary {

    private TextureLibrary() { }

    /** Edge length of every tile. Square, power of two, mipmappable. */
    public static final int SIZE = 128;

    public static final int MAT_NONE = 0;
    public static final int MAT_TARMAC = 1;
    public static final int MAT_DIRT = 2;
    public static final int MAT_CONCRETE = 3;
    public static final int MAT_GRASS = 4;
    public static final int MAT_SAND = 5;
    public static final int MAT_ROCK = 6;
    public static final int MAT_FACADE_OFFICE = 7;
    public static final int MAT_FACADE_APARTMENT = 8;
    public static final int MAT_FACADE_CHAWL = 9;
    public static final int MAT_FACADE_INFORMAL = 10;
    public static final int MAT_FACADE_SHOP = 11;
    public static final int MAT_ROOF_CONCRETE = 12;
    public static final int MAT_ROOF_TIN = 13;
    public static final int MAT_ROOF_TILE = 14;
    public static final int MAT_COUNT = 15;

    /**
     * Metres per tile repeat, indexed by material.
     *
     * <p>The facade entries are 6.2, which is two storeys at the 3.1 m floor
     * height the mesher uses. Two rows of windows per tile rather than one
     * halves how often the eye catches the repeat, and keeping it an exact
     * multiple of the floor height is what stops windows from slicing
     * through floor slabs.
     */
    public static final float[] SCALE_M = {
        1.0f,    // none
        8.0f,    // tarmac
        6.5f,    // dirt
        6.0f,    // concrete
        9.0f,    // grass
        7.0f,    // sand
        11.0f,   // rock
        6.2f,    // office
        6.2f,    // apartment
        6.2f,    // chawl
        6.2f,    // informal
        6.2f,    // shop
        5.0f,    // roof concrete
        4.0f,    // roof tin
        4.5f,    // roof tile
    };

    /** RGBA8888, row-major from the top. {@code SIZE * SIZE * 4} bytes. */
    public static byte[] tile(int material) {
        byte[] px = new byte[SIZE * SIZE * 4];
        switch (material) {
            case MAT_TARMAC: tarmac(px); break;
            case MAT_DIRT: dirt(px); break;
            case MAT_CONCRETE: concrete(px); break;
            case MAT_GRASS: grass(px); break;
            case MAT_SAND: sand(px); break;
            case MAT_ROCK: rock(px); break;
            case MAT_FACADE_OFFICE: office(px); break;
            case MAT_FACADE_APARTMENT: apartment(px); break;
            case MAT_FACADE_CHAWL: chawl(px); break;
            case MAT_FACADE_INFORMAL: informal(px); break;
            case MAT_FACADE_SHOP: shop(px); break;
            case MAT_ROOF_CONCRETE: roofConcrete(px); break;
            case MAT_ROOF_TIN: roofTin(px); break;
            case MAT_ROOF_TILE: roofTile(px); break;
            default: flat(px); break;
        }
        return px;
    }

    // ---------------------------------------------------------------- ground

    /**
     * Untextured white, with the emissive mask fully open.
     *
     * <p>Alpha is 1 here and 0 almost everywhere else, which looks backwards
     * until you remember what alpha is for in this atlas. Material 0 is what
     * props use - vehicle bodies, headlamps, tail lights - and those have no
     * window pattern to mask against. Leaving the mask shut would mean no
     * vehicle lamp could ever light up at night.
     */
    private static void flat(byte[] px) {
        for (int i = 0; i < SIZE * SIZE; i++) { put(px, i, 1, 1, 1, 1); }
    }

    private static void tarmac(byte[] px) {
        for (int y = 0; y < SIZE; y++) {
            for (int x = 0; x < SIZE; x++) {
                double u = x / (double) SIZE, v = y / (double) SIZE;
                // Fine aggregate over a slow blotch, so it reads as asphalt
                // close up and as uneven wear from a distance.
                double grit = fbm(11, u, v, 32, 2);
                double worn = fbm(12, u, v, 4, 2);
                double t = 0.78 + 0.20 * grit + 0.16 * (worn - 0.5);
                // A few pale chips of exposed stone.
                if (grit > 0.88) { t += 0.22; }
                put(px, y * SIZE + x, t, t * 1.005, t * 1.02, 0);
            }
        }
    }

    private static void dirt(byte[] px) {
        for (int y = 0; y < SIZE; y++) {
            for (int x = 0; x < SIZE; x++) {
                double u = x / (double) SIZE, v = y / (double) SIZE;
                double n = fbm(21, u, v, 8, 3);
                double stone = fbm(22, u, v, 40, 1);
                double t = 0.80 + 0.26 * (n - 0.5);
                if (stone > 0.90) { t += 0.16; }
                put(px, y * SIZE + x, t * 1.06, t * 0.97, t * 0.84, 0);
            }
        }
    }

    private static void concrete(byte[] px) {
        for (int y = 0; y < SIZE; y++) {
            for (int x = 0; x < SIZE; x++) {
                double u = x / (double) SIZE, v = y / (double) SIZE;
                double n = fbm(31, u, v, 6, 3);
                double t = 0.88 + 0.16 * (n - 0.5);
                // Monsoon staining runs downward, so the streaks are vertical.
                double streak = fbm(32, u * 6.0, v, 16, 2);
                t -= 0.10 * Math.max(0, streak - 0.60);
                put(px, y * SIZE + x, t, t * 0.995, t * 0.97, 0);
            }
        }
    }

    private static void grass(byte[] px) {
        for (int y = 0; y < SIZE; y++) {
            for (int x = 0; x < SIZE; x++) {
                double u = x / (double) SIZE, v = y / (double) SIZE;
                double n = fbm(41, u, v, 16, 3);
                double clump = fbm(42, u, v, 5, 2);
                double t = 0.80 + 0.30 * (n - 0.5) + 0.16 * (clump - 0.5);
                put(px, y * SIZE + x, t * 0.88, t * 1.06, t * 0.72, 0);
            }
        }
    }

    private static void sand(byte[] px) {
        for (int y = 0; y < SIZE; y++) {
            for (int x = 0; x < SIZE; x++) {
                double u = x / (double) SIZE, v = y / (double) SIZE;
                double n = fbm(51, u, v, 24, 2);
                // Ripples, which is what makes sand read as sand.
                double ripple = 0.5 + 0.5 * Math.sin((v * 18.0 + n * 1.4) * Math.PI * 2);
                double t = 0.90 + 0.10 * (n - 0.5) + 0.07 * (ripple - 0.5);
                put(px, y * SIZE + x, t * 1.06, t * 1.01, t * 0.86, 0);
            }
        }
    }

    private static void rock(byte[] px) {
        for (int y = 0; y < SIZE; y++) {
            for (int x = 0; x < SIZE; x++) {
                double u = x / (double) SIZE, v = y / (double) SIZE;
                double n = fbm(61, u, v, 8, 4);
                double t = 0.82 + 0.30 * (n - 0.5);
                put(px, y * SIZE + x, t * 0.98, t * 0.96, t * 0.94, 0);
            }
        }
    }

    // --------------------------------------------------------------- facades

    /**
     * Curtain-walled office. Two storeys tall, four bays wide, mullions
     * between. Glass is the emissive mask, so these are the towers that come
     * alive along the Bandra-Kurla skyline after dark.
     */
    private static void office(byte[] px) {
        // rows and cols must divide SIZE exactly or the last cell is a
        // fragment and the tile cannot wrap. 128 = 2 x 64 = 4 x 32.
        final int rows = 2, cols = 4;
        int ch = SIZE / rows, cw = SIZE / cols;
        for (int y = 0; y < SIZE; y++) {
            for (int x = 0; x < SIZE; x++) {
                int ry = y % ch, rx = x % cw;
                int bay = (y / ch) * cols + (x / cw);
                double u = x / (double) SIZE, v = y / (double) SIZE;
                double grime = fbm(71, u, v, 4, 2);
                boolean glass = ry > 3 && ry < ch - 4 && rx > 2 && rx < cw - 3;
                if (glass) {
                    // Each pane reflects the sky slightly differently.
                    double tint = 0.30 + 0.16 * hash(72, bay, 0);
                    double sheen = 0.14 * (1.0 - ry / (double) ch);
                    double t = tint + sheen;
                    put(px, y * SIZE + x, t * 0.80, t * 0.95, t * 1.10, 1.0);
                } else {
                    double t = 0.90 + 0.10 * (grime - 0.5);
                    // The spandrel band between floors is a touch darker.
                    if (ry <= 3 || ry >= ch - 4) { t *= 0.86; }
                    put(px, y * SIZE + x, t, t, t * 1.01, 0);
                }
            }
        }
    }

    /**
     * The commonest building in Mumbai: a rendered concrete apartment block
     * with deep balconies and window grilles. Four bays, two storeys.
     */
    private static void apartment(byte[] px) {
        // Two bays of 3.1 m across a 6.2 m tile, which both divides SIZE
        // and gives a believable room width.
        final int rows = 2, cols = 2;
        int ch = SIZE / rows, cw = SIZE / cols;
        for (int y = 0; y < SIZE; y++) {
            for (int x = 0; x < SIZE; x++) {
                int ry = y % ch, rx = x % cw;
                int row = y / ch, col = x / cw;
                double u = x / (double) SIZE, v = y / (double) SIZE;
                double wall = 0.92 + 0.12 * (fbm(81, u, v, 5, 3) - 0.5);
                // Water staining below every slab edge.
                double stain = fbm(82, u * 5.0, v, 16, 2);
                if (ry < ch * 0.30) { wall -= 0.13 * Math.max(0, stain - 0.45); }

                boolean window = ry > ch * 0.16 && ry < ch * 0.58
                        && rx > cw * 0.17 && rx < cw * 0.83;
                boolean balcony = ry >= ch * 0.58 && ry < ch * 0.80
                        && rx > cw * 0.10 && rx < cw * 0.90;

                if (window) {
                    double t = 0.34 + 0.10 * hash(83, row * 7 + col, 1);
                    // Grille bars, which every flat here has.
                    if ((rx % 5) == 0 || (ry % 6) == 0) { t += 0.26; }
                    put(px, y * SIZE + x, t * 0.94, t * 1.00, t * 1.06, 1.0);
                } else if (balcony) {
                    // Railing: alternating light bars over a shadowed recess.
                    double t = ((rx % 4) < 2) ? 0.70 : 0.42;
                    put(px, y * SIZE + x, t * 1.02, t, t * 0.96, 0);
                } else {
                    put(px, y * SIZE + x, wall * 1.02, wall, wall * 0.95, 0);
                }
            }
        }
    }

    /** Older low-rise: smaller openings, heavier weathering, no balcony. */
    private static void chawl(byte[] px) {
        final int rows = 2, cols = 2;
        int ch = SIZE / rows, cw = SIZE / cols;
        for (int y = 0; y < SIZE; y++) {
            for (int x = 0; x < SIZE; x++) {
                int ry = y % ch, rx = x % cw;
                double u = x / (double) SIZE, v = y / (double) SIZE;
                double age = fbm(91, u, v, 7, 3);
                double wall = 0.84 + 0.20 * (age - 0.5);
                double stain = fbm(92, u * 4.0, v, 12, 2);
                wall -= 0.16 * Math.max(0, stain - 0.40);
                boolean window = ry > ch * 0.22 && ry < ch * 0.56
                        && rx > cw * 0.26 && rx < cw * 0.74;
                if (window) {
                    double t = 0.30;
                    if ((rx % 4) == 0) { t += 0.22; }
                    put(px, y * SIZE + x, t, t * 1.02, t * 1.04, 1.0);
                } else {
                    // A painted plinth along the bottom of each storey.
                    if (ry > ch * 0.86) { wall *= 0.80; }
                    put(px, y * SIZE + x, wall * 1.04, wall * 0.99, wall * 0.90, 0);
                }
            }
        }
    }

    /**
     * Self-built housing: corrugated sheet and board, patched over time.
     *
     * <p>Rendered as what it is — a wall of mismatched but deliberately
     * maintained panels. No rubbish, no decay cues, no visual editorialising.
     * People live here and the brief was explicit about not caricaturing
     * that.
     */
    private static void informal(byte[] px) {
        for (int y = 0; y < SIZE; y++) {
            for (int x = 0; x < SIZE; x++) {
                double u = x / (double) SIZE, v = y / (double) SIZE;
                // Panel sizes and the corrugation period all divide SIZE,
                // so the sheet pattern continues across the tile join.
                int panelX = x / 16, panelY = y / 32;
                double hue = hash(101, panelX, panelY);
                double shade = 0.74 + 0.26 * hash(102, panelX, panelY);
                // Corrugation runs vertically down each sheet.
                double ridge = 0.5 + 0.5 * Math.sin(x * Math.PI * 2 / 8.0);
                double t = shade * (0.88 + 0.16 * ridge);
                // Panel edges.
                if ((x % 16) == 0 || (y % 32) == 0) { t *= 0.72; }
                double r = t, g = t, b = t;
                if (hue < 0.34) { r *= 1.10; g *= 0.98; b *= 0.86; }
                else if (hue < 0.62) { r *= 0.88; g *= 1.02; b *= 1.08; }
                else { r *= 1.02; g *= 1.04; b *= 0.94; }
                boolean window = (x % 16) > 4 && (x % 16) < 12
                        && (y % 32) > 10 && (y % 32) < 22 && hue > 0.72;
                if (window) {
                    put(px, y * SIZE + x, 0.34, 0.33, 0.31, 1.0);
                } else {
                    put(px, y * SIZE + x, r, g, b, 0);
                }
            }
        }
    }

    /** Ground-floor retail: shutters, signage band, deep awning shadow. */
    private static void shop(byte[] px) {
        final int cols = 2;
        int cw = SIZE / cols;
        for (int y = 0; y < SIZE; y++) {
            for (int x = 0; x < SIZE; x++) {
                int rx = x % cw;
                double u = x / (double) SIZE, v = y / (double) SIZE;
                double wall = 0.90 + 0.14 * (fbm(111, u, v, 6, 3) - 0.5);
                if (v > 0.62) {
                    // Roller shutter: fine horizontal ribs.
                    double rib = 0.5 + 0.5 * Math.sin(y * Math.PI * 2 / 8.0);
                    double t = (0.52 + 0.18 * rib) * (0.92 + 0.16 * hash(112, x / cw, 0));
                    if (rx < 2 || rx > cw - 3) { t *= 0.70; }
                    put(px, y * SIZE + x, t * 1.02, t, t * 0.95, 0);
                } else if (v > 0.47) {
                    // Signboard. Bright, blank: no lettering, no brands.
                    double h2 = hash(113, x / cw, 1);
                    double r = 0.55 + 0.45 * h2, g = 0.40 + 0.40 * hash(114, x / cw, 2);
                    double b = 0.35 + 0.45 * hash(115, x / cw, 3);
                    if (rx < 2 || rx > cw - 3 || v < 0.49 || v > 0.60) {
                        r *= 0.6; g *= 0.6; b *= 0.6;
                    }
                    put(px, y * SIZE + x, r, g, b, 1.0);
                } else {
                    put(px, y * SIZE + x, wall * 1.02, wall, wall * 0.96, 0);
                }
            }
        }
    }

    // ----------------------------------------------------------------- roofs

    private static void roofConcrete(byte[] px) {
        for (int y = 0; y < SIZE; y++) {
            for (int x = 0; x < SIZE; x++) {
                double u = x / (double) SIZE, v = y / (double) SIZE;
                double n = fbm(121, u, v, 10, 3);
                double t = 0.82 + 0.22 * (n - 0.5);
                // Pooled water and patched waterproofing.
                double pool = fbm(122, u, v, 4, 2);
                if (pool > 0.66) { t *= 0.86; }
                put(px, y * SIZE + x, t * 0.99, t, t * 1.01, 0);
            }
        }
    }

    private static void roofTin(byte[] px) {
        for (int y = 0; y < SIZE; y++) {
            for (int x = 0; x < SIZE; x++) {
                double u = x / (double) SIZE, v = y / (double) SIZE;
                double ridge = 0.5 + 0.5 * Math.sin(x * Math.PI * 2 / 8.0);
                double rust = fbm(131, u, v, 7, 3);
                double t = (0.72 + 0.26 * ridge) * (0.90 + 0.18 * (rust - 0.5));
                double r = t, g = t, b = t;
                if (rust > 0.58) {
                    double k = (rust - 0.58) / 0.42;
                    r = t * (1.0 + 0.30 * k); g = t * (1.0 - 0.10 * k); b = t * (1.0 - 0.26 * k);
                }
                // Sheet joins every third corrugation.
                if ((x % 32) < 2) { r *= 0.78; g *= 0.78; b *= 0.78; }
                put(px, y * SIZE + x, r, g, b, 0);
            }
        }
    }

    private static void roofTile(byte[] px) {
        final int th = 16, tw = 16;
        for (int y = 0; y < SIZE; y++) {
            for (int x = 0; x < SIZE; x++) {
                int row = y / th;
                // Alternate courses offset by half a tile, as laid.
                int sx = (x + (row % 2) * (tw / 2)) % tw;
                int ry = y % th;
                double u = x / (double) SIZE, v = y / (double) SIZE;
                double n = fbm(141, u, v, 9, 2);
                double curve = 0.5 + 0.5 * Math.sin(sx * Math.PI / tw);
                double t = (0.70 + 0.30 * curve) * (0.92 + 0.16 * (n - 0.5));
                if (ry < 2) { t *= 0.66; }           // shadow under the lap
                put(px, y * SIZE + x, t * 1.14, t * 0.86, t * 0.72, 0);
            }
        }
    }

    // ------------------------------------------------------------- machinery

    private static void put(byte[] px, int i, double r, double g, double b, double a) {
        int o = i * 4;
        px[o] = u8(r);
        px[o + 1] = u8(g);
        px[o + 2] = u8(b);
        px[o + 3] = u8(a);
    }

    private static byte u8(double v) {
        int i = (int) Math.round(v * 255.0);
        if (i < 0) { i = 0; }
        if (i > 255) { i = 255; }
        return (byte) i;
    }

    /** Deterministic lattice hash in [0, 1). No {@code Random}: this must
     *  produce the same atlas on every device and every run. */
    static double hash(int seed, int x, int y) {
        int h = seed * 374761393 + x * 668265263 + y * 1274126177;
        h ^= h >>> 13;
        h *= 1274126177;
        h ^= h >>> 16;
        return (h & 0x00FFFFFF) / (double) 0x01000000;
    }

    /**
     * Value noise that wraps on {@code period}. The wrap is the whole point:
     * {@code floorMod} makes the lattice column at {@code period} the same
     * one as at zero, so the tile joins itself.
     */
    private static double vnoise(int seed, double x, double y, int period) {
        int x0 = (int) Math.floor(x), y0 = (int) Math.floor(y);
        double fx = x - x0, fy = y - y0;
        double sx = fx * fx * (3 - 2 * fx);
        double sy = fy * fy * (3 - 2 * fy);
        int xa = Math.floorMod(x0, period), xb = Math.floorMod(x0 + 1, period);
        int ya = Math.floorMod(y0, period), yb = Math.floorMod(y0 + 1, period);
        double n00 = hash(seed, xa, ya), n10 = hash(seed, xb, ya);
        double n01 = hash(seed, xa, yb), n11 = hash(seed, xb, yb);
        return (n00 * (1 - sx) + n10 * sx) * (1 - sy)
             + (n01 * (1 - sx) + n11 * sx) * sy;
    }

    /**
     * Fractal sum of wrapping noise. Each octave doubles the period, so every
     * octave tiles and therefore so does the sum.
     */
    static double fbm(int seed, double u, double v, int basePeriod, int octaves) {
        double sum = 0, amp = 1, norm = 0;
        int period = basePeriod;
        for (int o = 0; o < octaves; o++) {
            sum += amp * vnoise(seed + o * 101, u * period, v * period, period);
            norm += amp;
            amp *= 0.5;
            period *= 2;
        }
        return sum / norm;
    }
}
